CREATE COLUMN TABLE "TEST_AP"."ITL1" ("LogEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50) NOT NULL , "SysNumber" INTEGER CS_INT NOT NULL , "Quantity" DECIMAL(21,6) CS_FIXED, "AllocQty" DECIMAL(21,6) CS_FIXED, "MdAbsEntry" INTEGER CS_INT, "ReleaseQty" DECIMAL(21,6) CS_FIXED, "PickedQty" DECIMAL(21,6) CS_FIXED, "OrderedQty" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("LogEntry", "ItemCode", "SysNumber")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ITL1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$ItemCode$SysNumber$','ItemCode','SysNumber'));
CREATE INDEX "ITL1_SNB_SYSID" ON "TEST_AP"."ITL1" ( "ItemCode" ASC, "SysNumber" ASC )